<div class="page-header"><h1>Galería de eventos</h1><p>Así vivimos algunos de los eventos con las máquinas de Crazy4Arcade.</p></div>
<?php if (!$eventos): ?><p class="empty-state">Próximamente compartiremos aquí fotos de nuestros eventos.</p><?php else: ?><div class="gallery-grid"><?php foreach ($eventos as $evento): $fotos=$porEvento[(int)$evento['id']] ?? []; if (!$fotos) continue; $portada=$fotos[0]; ?><article class="gallery-event"><div class="gallery-event-cover"><img src="<?= e($portada['imagen_url']) ?>" alt="<?= e($portada['texto_alternativo'] ?: $evento['titulo']) ?>" onerror="this.src='/img/placeholder.svg'"></div><div class="gallery-event-body"><span class="gallery-event-date"><?= $evento['fecha_evento'] ? e(date('d/m/Y', strtotime($evento['fecha_evento']))) : 'Evento Crazy4Arcade' ?></span><h2><?= e($evento['titulo']) ?></h2><?php if ($evento['descripcion']): ?><p><?= e($evento['descripcion']) ?></p><?php endif; ?></div><?php if (count($fotos)>1): ?><div class="gallery-thumbs"><?php foreach (array_slice($fotos,1) as $foto): ?><img src="<?= e($foto['imagen_url']) ?>" alt="<?= e($foto['texto_alternativo'] ?: $evento['titulo']) ?>" loading="lazy" onerror="this.src='/img/placeholder.svg'"><?php endforeach; ?></div><?php endif; ?></article><?php endforeach; ?></div><?php endif; ?>
